 * Sets up the `expo-router` integration: enables the router's navigation events and
 * subscribes to them so interactivity metrics can be attributed to the focused route.
 * Initialization is idempotent — repeated calls are no-ops after the first.
 */

interface NavigationEvents {
  enable?: () => void;
  saveCurrentPathname?: () => void;
  addListener?: (
    type: 'pageFocused',
    callback: (event: { pathname: string; params: Record<string, string> }) => void
  ) => void;
}

interface RouterGlobal {
  navigationEvents?: NavigationEvents;
}

function getRouterGlobal(): RouterGlobal | undefined {
  if (globalThis && globalThis.expo && 'router' in globalThis.expo) {
    return (globalThis.expo as { router?: RouterGlobal }).router;
  }
  return undefined;
}

let initialized = false;

/**
 * Whether the router integration has already been initialized.
 */
export function isInitialized(): boolean {
  return initialized;
}

/**
 * Enables the router navigation events and subscribes to them. Returns a function
 * that tears down the subscription.
 */
export function initListeners(): () => void {
  const router = getRouterGlobal();
  router?.navigationEvents?.enable?.();
  router?.navigationEvents?.saveCurrentPathname?.();
  // The router global does not expose an unsubscribe handle, so cleanup is a no-op.
  return () => {};
}

/**
 * Initializes the router integration exactly once.
 */
export function initRouterIntegration(): void {
  if (initialized) {
    return;
  }
  initialized = true;
  initListeners();
}
