import { optionalRouter } from './router';

/**
 * Router-aware variant of the interactivity marker. When `expo-router` is installed,
 * it returns a function that marks the current interaction against the focused route's
 * `pathname`. If the current screen is not focused, marking is skipped. When the router
 * is not installed, it returns `null` so callers can fall back to the plain marker.
 */
export function useObserveForRouter(): ((options?: Record<string, unknown>) => Promise<void> | void) | null {
  if (!optionalRouter) {
    return null;
  }

  optionalRouter.useRoute();
  const navigation = optionalRouter.useNavigation();
  const routeInfo = optionalRouter.useCurrentRouteInfo();

  return (options?: Record<string, unknown>) => {
    if (!navigation.isFocused()) {
      return;
    }
    return AppMetrics.markInteractive({ ...options, routeName: routeInfo.pathname });
  };
}
